6	/**
7	 * The eShopOnContainers WebSPA Angular holdout ledger entry.
8	 *
9	 * This is the third published holdout and the first one whose migrated lane
10	 * reached a build. It is published for the same reason the two failures were:
11	 * an adapter that only publishes the applications it carried is not evidence,
12	 * and an adapter that publishes a partial success as a whole one is worse.
13	 *
14	 * What this record states, in the order it happened:
15	 *
16	 * 1. Gate zero passed — but only because the T022 follow-up ruling overturned
17	 *    the pre-Ivy screen verdict on this candidate under the successor-across-
18	 *    names rule. The original screen text is unchanged and the overturn is
19	 *    named rather than absorbed.
20	 * 2. RED at install under the frozen `f1a63359` composite (T023 u5), with zero
21	 *    adapter bytes changed, five gaps itemised and no closure linked. That
22	 *    record stands; it is history, not a draft.
23	 * 3. GREEN migrated production build after the board-authorized T024 Angular
24	 *    reopen: `npm run build:prod` exits 0 and two full runs are byte-identical.
25	 *
26	 * And what it does not state: no witness journey has been run, in either lane,
27	 * so nothing here is a browser proof and nothing here is a passed holdout. The
28	 * outcome field says exactly that and nothing more.
29	 *
30	 * Every field is derived from the sealed run evidence rather than authored
31	 * here, so the entry cannot drift away from what the runs measured.
32	 */
33	export const HOLDOUT_ANGULAR_ESHOP_WEBSPA_SCHEMA =
34		'versionless.holdout-angular-eshop-webspa.v1' as const;
