316	function record(value: unknown, label: string): Record<string, unknown> {
317		if (typeof value !== 'object' || value === null || Array.isArray(value))
318			throw new Error(`${label} is not an object`);
319		return value as Record<string, unknown>;
320	}
321	
322	function text(value: unknown, label: string): string {
323		if (typeof value !== 'string' || value.length === 0) throw new Error(`${label} is not a string`);
324		return value;
325	}
326	
327	function count(value: unknown, label: string): number {
328		if (typeof value !== 'number' || !Number.isInteger(value))
329			throw new Error(`${label} is not an integer`);
330		return value;
331	}
