333	/** The canonical digest of an entry, taken with the digest field emptied. */
334	export function holdoutAngularEshopWebspaDigest(
335		receipt: HoldoutAngularEshopWebspaReceipt,
336	): string {
337		const copy = structuredClone(receipt);
338		copy.integrity.canonicalDigest = '';
339		return sha256(canonicalize(copy));
340	}
