342	/**
343	 * Reads the sealed attempt record and rebuilds the entry from it.
344	 *
345	 * The three states this application passed through are each asserted against
346	 * the record separately — gate zero overturned, install RED under the frozen
347	 * composite, build green twice under the reopen — so an entry that has quietly
348	 * lost one of them cannot be derived.
349	 */
350	export async function deriveHoldoutAngularEshopWebspaReceipt(
351		rootDir = '.',
352	): Promise<HoldoutAngularEshopWebspaReceipt> {
353		const root = resolve(rootDir);
354		for (const evidence of HOLDOUT_ANGULAR_ESHOP_WEBSPA_RUN_EVIDENCE) {
355			const bytes = await readFile(join(root, evidence.path));
356			if (sha256(bytes.toString('utf8')) !== evidence.sha256)
357				throw new Error(`eShop WebSPA holdout run evidence changed: ${evidence.path}`);
358		}
359		const attempt = record(
360			JSON.parse(await readFile(join(root, HOLDOUT_ANGULAR_ESHOP_WEBSPA_ATTEMPT_PATH), 'utf8')),
361			'eShop WebSPA attempt record',
362		);
363		const attemptText = JSON.stringify(attempt);
364		const candidate = record(attempt.candidate, 'eShop WebSPA candidate');
365		const gateZero = record(attempt.gateZero, 'eShop WebSPA gate zero');
366		const licenseAtPin = record(gateZero.licenseAtPin, 'eShop WebSPA license at pin');
367		const boundary = record(gateZero.boundary, 'eShop WebSPA gate-zero boundary');
368		const detect = record(attempt.detect, 'eShop WebSPA detection');
369		const angular = record(detect.angular, 'eShop WebSPA Angular detection');
370		const cliGeneration = record(detect.angularCliGeneration, 'eShop WebSPA CLI generation');
371		const baseline = record(attempt.baseline, 'eShop WebSPA baseline');
372		const identityCheck = record(baseline.identityCheck, 'eShop WebSPA archive identity');
373		const eraCell = record(baseline.eraCell, 'eShop WebSPA era cell');
374		const determinism = record(baseline.determinism, 'eShop WebSPA baseline determinism');
375		const run1VsRun2 = record(determinism.run1VsRun2, 'eShop WebSPA baseline run comparison');
376		const migration = record(attempt.migration, 'eShop WebSPA migration');
377		const application = record(migration.application, 'eShop WebSPA migrated application');
378		const laneInstall = record(migration.laneInstall, 'eShop WebSPA migrated lane install');
379		const targetBuild = record(migration.targetBuild, 'eShop WebSPA migrated target build');
380		const green = record(attempt.t024U4Rerun, 'eShop WebSPA T024 u4 re-run');
381		const greenInstall = record(green.laneInstall, 'eShop WebSPA green lane install');
382		const greenBuild = record(green.targetBuild, 'eShop WebSPA green target build');
383		const outputInventory = record(green.outputInventory, 'eShop WebSPA green output inventory');
384		const changesetCounts = record(green.changesetCounts, 'eShop WebSPA green changeset counts');
385	
386		// Gate zero passed on a ruling, not on the screen. Both are asserted so the
387		// entry cannot present the overturn as an ordinary pass.
388		if (
389			!text(boundary.ruledVerdict, 'eShop WebSPA gate-zero ruled verdict').startsWith('pass') ||
390			boundary.originalScreenTextUnchanged !== true
391		)
392			throw new Error('eShop WebSPA gate-zero record no longer states an overturned pass');
393		// The install RED under the frozen composite is history and must stay in the
394		// record; a re-run that overwrote it would be caught here.
395		if (
396			migration.outcome !== 'red-migration-gaps-itemised' ||
397			targetBuild.produced !== false ||
398			targetBuild.attempted !== false ||
399			count(laneInstall.packagesInstalled, 'eShop WebSPA packages installed') !== 0
400		)
401			throw new Error('eShop WebSPA install RED under the frozen composite is no longer recorded');
402		if (
403			!text(migration.holdoutPosition, 'eShop WebSPA holdout position').includes(
404				HOLDOUT_ANGULAR_ESHOP_WEBSPA_FROZEN_FINGERPRINT,
405			)
406		)
407			throw new Error('eShop WebSPA RED was not measured under the recorded frozen composite');
408		// The green build is asserted at the same strength: exit zero, two runs, and
409		// byte-identical output, or there is no green to publish.
410		if (
411			green.outcome !== 'green-build-twice-byte-identical' ||
412			greenBuild.produced !== true ||
413			greenBuild.exitStatus !== 0 ||
414			greenBuild.byteIdenticalAcrossRuns !== true ||
415			count(greenBuild.runs, 'eShop WebSPA green build runs') !== 2 ||
416			greenInstall.exitStatus !== 0 ||
417			greenInstall.forcedFlagsUsed !== false ||
418			greenInstall.narrowingApplied !== false ||
419			count(changesetCounts.handEdits, 'eShop WebSPA hand edits') !== 0
420		)
421			throw new Error('eShop WebSPA green build record no longer states a repeatable clean build');
422		if (
423			!Array.isArray(greenBuild.remainingDiagnostics) ||
424			greenBuild.remainingDiagnostics.length !== 0
425		)
426			throw new Error('eShop WebSPA green build record no longer states zero diagnostics');
427		if (
428			!text(green.authorization, 'eShop WebSPA reopen authorization').includes(
429				HOLDOUT_ANGULAR_ESHOP_WEBSPA_REACT_SUBTREE,
430			)
431		)
432			throw new Error('eShop WebSPA reopen record no longer names the untouched React subtree');
433		// Every capability the reopen is credited with has to be findable in the run
434		// record. A list nobody can check against the evidence is a list.
435		for (const entry of HOLDOUT_ANGULAR_ESHOP_WEBSPA_REOPEN_CAPABILITIES)
436			for (const marker of entry.markers)
437				if (!attemptText.includes(marker))
438					throw new Error(`eShop WebSPA run record omits ${entry.capability}: ${marker}`);
439		if (HOLDOUT_ANGULAR_ESHOP_WEBSPA_REOPEN_CAPABILITIES.length !== 9)
440			throw new Error('eShop WebSPA reopen is not the declared nine capabilities');
441		// The whole point of the entry: the build is green and no journey ran. If the
442		// run record ever stops saying the second half, the entry stops deriving.
443		// The cell below is authored as four fields rather than one prose string, so
444		// it is checked back against the prose the run recorded: every part of it has
445		// to appear in the target the attempt declares.
446		const target = text(application.target, 'eShop WebSPA target declaration');
447		for (const part of ['angular-16-browser-builder', '16.2', '@angular-devkit/build-angular:browser', '16.20.2'])
448			if (!target.includes(part))
449				throw new Error(`eShop WebSPA target cell no longer declares ${part}`);
450		if (run1VsRun2.byteIdentical !== true)
451			throw new Error('eShop WebSPA era baseline is no longer recorded byte-reproducible');
452		if (
