707	
708	/**
709	 * The corpus and aggregate record for this holdout.
710	 *
711	 * It follows the two failed holdout records field for field, including the one
712	 * field that matters most: `countedInLineageNumerator` is false and stays
713	 * false. A build is not a vertical. The record carries both adapter states and
714	 * the witness state so that no consumer of the ledger can read the green build
715	 * as a proven migration.
716	 */
717	export function holdoutAngularEshopWebspaCorpusRecord(
718		receipt: HoldoutAngularEshopWebspaReceipt,
719	) {
720		return {
721			id: 'holdout-angular-eshop-webspa',
722			application: receipt.application,
