734				subtree: receipt.frozenAdapter.authorizedReopen.subtree,
735				capabilitiesExtracted: receipt.frozenAdapter.authorizedReopen.capabilitiesExtracted,
736				angularSubtreeOidAtGreen: receipt.frozenAdapter.authorizedReopen.angularSubtreeOidAtGreen,
737				refreezeComposite: receipt.frozenAdapter.authorizedReopen.refreezeComposite,
738				outcomeAfterReopen: receipt.holdoutOutcome,
739			},
740			baselineLane: receipt.lanes.baseline.outcome,
741			migratedLaneUnderFreeze: receipt.lanes.migratedUnderFreeze.outcome,
742			migratedLane: receipt.lanes.migratedAfterReopen.outcome,
743			attempts: receipt.lanes.migratedAfterReopen.buildRuns,
744			witness: receipt.witness.state,
745			receipt: HOLDOUT_ANGULAR_ESHOP_WEBSPA_RECEIPT_PATH,
746			digest: receipt.integrity.canonicalDigest,
747			countedInLineageNumerator: false,
748			countingNote:
749				'Never counted in any lineage numerator. The migrated production build is green and repeatable, but no witness journey has run, so no application is proven migrated: this entry is a measured state published in full, not a vertical and not a pass. The install RED under the frozen f1a63359 composite is retained beside it as the record of what the frozen adapter did.',
