754	export async function verifyHoldoutAngularEshopWebspaEvidence(rootDir = '.'): Promise<{
755		valid: true;
756		digest: string;
757		artifacts: number;
758		receipt: HoldoutAngularEshopWebspaReceipt;
759	}> {
