761		const published = parseHoldoutAngularEshopWebspaReceipt(
762			JSON.parse(await readFile(join(root, HOLDOUT_ANGULAR_ESHOP_WEBSPA_RECEIPT_PATH), 'utf8')),
763		);
764		const derived = await deriveHoldoutAngularEshopWebspaReceipt(root);
765		if (canonicalize(published) !== canonicalize(derived))
