312			}),
313		);
314	}
315	
316	export function witnessAngularEshopWebspaDigest(
317		receipt: WitnessAngularEshopWebspaReceipt,
318	): string {
319		const { integrity, ...rest } = receipt;
320		void integrity;
321		return sha256(canonicalize(rest));
322	}
323	
324	const fail = (message: string): never => {
325		throw new Error(message);
326	};
327	
328	export function parseWitnessAngularEshopWebspaReceipt(
329		value: unknown,
330	): WitnessAngularEshopWebspaReceipt {
331		const receipt = value as WitnessAngularEshopWebspaReceipt;
332		if (receipt.schemaVersion !== WITNESS_ANGULAR_ESHOP_WEBSPA_SCHEMA)
333			fail('eShop WebSPA Witness schema version differs');
334		if (receipt.result !== 'pass') fail('eShop WebSPA Witness result is not a pass');
335		if (receipt.app !== WITNESS_ANGULAR_ESHOP_WEBSPA_APP) fail('eShop WebSPA Witness app differs');
336		if (receipt.adapterComposite !== WITNESS_ANGULAR_ESHOP_WEBSPA_ADAPTER_COMPOSITE)
337			fail('eShop WebSPA Witness adapter composite differs');
338		if (receipt.runs.length !== 4) fail('eShop WebSPA Witness must record two lanes observed twice');
339		const projection = receipt.projection;
340		if (
341			projection.state !== 'frozen-synthetic-loopback-projection' ||
342			projection.transport !== 'same-origin-bounded-loopback-api' ||
343			projection.identicalAcrossLanes !== true ||
344			projection.behaviorDigest !== WITNESS_ANGULAR_ESHOP_WEBSPA_PROJECTION_BEHAVIOR_DIGEST
345		)
346			fail('eShop WebSPA Witness projection declaration differs');
347		const ledger = projection.ledger;
348		if (ledger.refusedUnknown !== 0)
349			fail('eShop WebSPA Witness projection refused a path the application asked for');
350		if (ledger.refusedUnprojected !== 0)
351			fail('eShop WebSPA Witness projection withheld a path the application asked for');
352		if (ledger.apiRecords !== ledger.served)
353			fail('eShop WebSPA Witness projection served fewer records than it answered');
354		if (ledger.declinedNonApi < 1)
355			fail('eShop WebSPA Witness projection declined no static request');
356		if (ledger.records !== ledger.apiRecords + ledger.declinedNonApi)
357			fail('eShop WebSPA Witness projection ledger does not account for every record');
358		if (ledger.entries.reduce((sum, entry) => sum + entry.count, 0) !== ledger.apiRecords)
359			fail('eShop WebSPA Witness projection ledger entries do not sum to its API records');
360		const semantic = new Map<string, string>();
361		for (const run of receipt.runs) {
362			if (run.result !== 'pass') fail('eShop WebSPA Witness run is not a pass');
363			if (run.semanticDigest !== witnessAngularEshopWebspaRawDigest(run))
364				fail('eShop WebSPA Witness run semantic digest differs');
365			if (run.behaviorDigest !== witnessAngularEshopWebspaBehaviorDigest(run))
366				fail('eShop WebSPA Witness run behavior digest differs');
367			if (run['successfulNonLoopback'] !== 0)
368				fail('eShop WebSPA Witness run reached a non-loopback origin');
369			const held = semantic.get(run.lane);
370			if (held === undefined) semantic.set(run.lane, run.semanticDigest);
371			else if (held !== run.semanticDigest)
372				fail('eShop WebSPA Witness repeated pass differs');
373		}
374		if (semantic.size !== 2) fail('eShop WebSPA Witness did not observe both lanes');
375		if (new Set(receipt.runs.map((run) => run.behaviorDigest)).size !== 1)
376			fail('eShop WebSPA Witness two-lane behavior parity differs');
377		if (receipt.parity.behaviorDigest !== receipt.runs[0]!.behaviorDigest)
378			fail('eShop WebSPA Witness parity digest differs from its runs');
379		const mutation = receipt.mutation;
380		if (
381			mutation.intendedFailure !== true ||
382			mutation.lane !== 'migrated' ||
383			mutation.seam !== WITNESS_ANGULAR_ESHOP_WEBSPA_MUTATION_SEAM ||
384			mutation.restoredByteIdentically !== true ||
385			mutation.restoredRun !== 'pass' ||
386			mutation.beforeSha256 !== mutation.afterRestoreSha256 ||
387			mutation.mutatedSha256 === mutation.beforeSha256
388		)
389			fail('eShop WebSPA Witness mutation proof differs');
390		if (mutation.restoredBehaviorDigest !== receipt.parity.behaviorDigest)
391			fail('eShop WebSPA Witness restored behavior differs from the parity digest');
392		if (receipt.locality.successfulNonLoopback !== 0 || receipt.locality.osWideIsolation !== false)
393			fail('eShop WebSPA Witness locality differs');
394		if (
395			canonicalize(receipt.journey.surfaceLimits) !==
396			canonicalize(WITNESS_ANGULAR_ESHOP_WEBSPA_SURFACE_LIMITS)
397		)
398			fail('eShop WebSPA Witness surface limits differ');
399		if (receipt.integrity.canonicalDigest !== witnessAngularEshopWebspaDigest(receipt))
400			fail('eShop WebSPA Witness integrity digest differs');
401		return receipt;
402	}
403	
404	export function renderWitnessAngularEshopWebspaReceipt(
405		receipt: WitnessAngularEshopWebspaReceipt,
406	): string {
407		const lines: string[] = [];
408		lines.push('# eShop WebSPA holdout — browser-parity Witness');
409		lines.push('');
410		lines.push(`- Result: ${receipt.result}`);
411		lines.push(`- Unit: ${receipt.unit}`);
412		lines.push(`- Fixture: ${receipt.fixture}`);
413		lines.push(`- Source: ${receipt.source.repository}@${receipt.source.revision}`);
414		lines.push(`- Adapter composite: ${receipt.adapterComposite}`);
415		lines.push(`- Behavior parity digest: ${receipt.parity.behaviorDigest}`);
416		lines.push(`- Canonical digest: ${receipt.integrity.canonicalDigest}`);
417		lines.push('');
418		lines.push('## Lanes');
419		lines.push('');
420		lines.push('| Lane | Output | Files | Inventory sha256 | Semantic digest |');
421		lines.push('| --- | --- | --- | --- | --- |');
422		for (const lane of ['baseline', 'migrated'] as const)
423			lines.push(
424				`| ${lane} | ${receipt.lanes[lane].output} | ${String(receipt.lanes[lane].files)} | ${receipt.lanes[lane].sha256} | ${receipt.parity.semanticDigestsPerLane[lane]} |`,
425			);
426		lines.push('');
427		lines.push('## Declared same-origin projection');
428		lines.push('');
429		lines.push(`- Label: ${receipt.projection.label}`);
430		lines.push(`- Transport: ${receipt.projection.transport}`);
431		lines.push(`- Behavior digest: ${receipt.projection.behaviorDigest}`);
432		lines.push(`- Seed: ${receipt.projection.seedFixture} (${receipt.projection.seedSha256})`);
433		lines.push(
434			`- Ledger: ${String(receipt.projection.ledger.served)} served, ${String(receipt.projection.ledger.refusedUnknown)} refused-unknown, ${String(receipt.projection.ledger.refusedUnprojected)} refused-unprojected, ${String(receipt.projection.ledger.declinedNonApi)} declined-non-api`,
435		);
436		lines.push('- Identical across both lanes: yes');
437		lines.push('');
438		lines.push('## Surface limits');
439		lines.push('');
440		for (const limit of receipt.journey.surfaceLimits)
441			lines.push(`- **${limit.surface}** (${limit.state}) — ${limit.reason}`);
442		lines.push('');
443		lines.push('## Mutation');
444		lines.push('');
445		lines.push(`- Seam: \`${receipt.mutation.seam}\` in ${receipt.mutation.path}`);
446		lines.push(`- Before: ${receipt.mutation.beforeSha256}`);
447		lines.push(`- Mutated: ${receipt.mutation.mutatedSha256}`);
448		lines.push(`- After restore: ${receipt.mutation.afterRestoreSha256}`);
449		lines.push(`- Restored run: ${receipt.mutation.restoredRun}`);
450		lines.push('');
451		lines.push('## Non-claims');
452		lines.push('');
453		for (const nonclaim of receipt.nonclaims) lines.push(`- ${nonclaim}`);
454		lines.push('');
455		return lines.join('\n');
456	}
