11	/**
12	 * The cypress-realworld-app holdout — the PASSING witness receipt, re-run under
13	 * the FROZEN adapter.
14	 *
15	 * The tranche-one FAIL (composite d9f75ef6) and the T017 re-run FAIL (composite
16	 * 5de7df56) are immutable and stay published. This receipt is the strictly-later
17	 * record that closes the freeze's holdout clause: the same application at the
18	 * same pinned revision is carried by the adapter re-frozen at composite
19	 * 4df7bc96, and its two-lane behaviour journey is measured green on a live
20	 * loopback backend. Nothing here is authored: every field is derived from the
21	 * committed measured run evidence, whose exact bytes are bound inside the
22	 * derivation, and the parity + pass-twice-determinism verdict is recomputed by
23	 * the SAME gate the calibration driver used, so the receipt cannot drift away
24	 * from what the browser measured.
25	 *
26	 * This is a holdout receipt, not a certification: it shows the frozen adapter
27	 * carrying one further application end to end, not generic support, and it is
28	 * counted in no lineage numerator.
29	 */
30	export const HOLDOUT_REACT_CYPRESS_RWA_WITNESS_SCHEMA =
31		'versionless.holdout-react-cypress-rwa-witness.v1' as const;
32	export const HOLDOUT_REACT_CYPRESS_RWA_WITNESS_RECEIPT_PATH =
33		'evidence/runs/holdout-react-cypress-rwa/green-2026-08-13/receipt.json' as const;
