254		const root = resolve(rootDir);
255		for (const evidence of HOLDOUT_REACT_CYPRESS_RWA_WITNESS_RUN_EVIDENCE) {
256			const bytes = await readFile(join(root, evidence.path));
257			if (sha256(bytes) !== evidence.sha256)
258				throw new Error(`Cypress RWA witness holdout run evidence drifted: ${evidence.path}`);
259		}
260	
261		// The frozen adapter's build measurement.
262		const build = witnessRecord(
263			JSON.parse(
264				await readFile(
265					join(root, HOLDOUT_REACT_CYPRESS_RWA_WITNESS_RUN_EVIDENCE[1]!.path),
266					'utf8',
267				),
268			),
269			'build profile',
270		);
271		if (
272			build.schemaVersion !== 'versionless.react-cypress-rwa-green-build-profile.v1' ||
273			build.role !== 'holdout' ||
274			build.fixture !== HOLDOUT_REACT_CYPRESS_RWA_WITNESS_FIXTURE ||
275			build.result !== 'migrated-green'
276		)
277			throw new Error('Cypress RWA witness holdout build profile identity differs');
278		const source = witnessRecord(build.source, 'source');
279		const migratedLane = witnessRecord(build.migratedLane, 'migrated lane');
280		if (migratedLane.result !== 'green')
281			throw new Error('Cypress RWA witness holdout migrated build is not green');
282		const outputDigest = witnessRecord(migratedLane.outputDigest, 'output digest');
283		const appChanged = witnessRecord(build.applicationFilesChanged, 'application files changed');
284		if (witnessCount(appChanged.count, 'application files changed count') !== 0)
285			throw new Error('Cypress RWA witness holdout changed application source');
286	
287		// The measured journey.
288		const parityDoc = witnessRecord(
289			JSON.parse(
290				await readFile(
291					join(root, HOLDOUT_REACT_CYPRESS_RWA_WITNESS_RUN_EVIDENCE[0]!.path),
292					'utf8',
293				),
294			),
295			'parity document',
296		);
297		if (!Array.isArray(parityDoc.passes) || parityDoc.passes.length !== 4)
298			throw new Error('Cypress RWA witness holdout parity document must carry four passes');
299		const measuredPasses = parityDoc.passes.map((pass, index) => {
300			const entry = witnessRecord(pass, `pass[${index}]`);
301			return witnessRecord(entry.measured, `pass[${index}].measured`) as unknown as
302				WitnessReactCypressRwaMeasuredPass;
303		});
304		// Recompute the two-lane parity + pass-twice determinism verdict from the
305		// measured passes: this reproves 51/51 both lanes, one behaviour digest, each
306		// lane deterministic across its two passes, zero successful non-loopback, and
307		// no seed marker, or throws.
308		const parity = summarizeWitnessReactCypressRwaTwoLaneParity(measuredPasses);
309		const recordedParity = witnessRecord(parityDoc.parity, 'recorded parity');
310		if (recordedParity.behaviorDigest !== parity.behaviorDigest)
311			throw new Error('Cypress RWA witness holdout recorded parity does not match recomputed');
312	
313		const firstBaseline = measuredPasses.find(
314			(pass) => pass.lane === 'baseline' && pass.pass === 1,
315		)!;
316		const firstMigrated = measuredPasses.find(
317			(pass) => pass.lane === 'migrated' && pass.pass === 1,
318		)!;
