469			receipt.frozenAdapter.changesProposedAndExecuted !== 0 ||
470			receipt.frozenAdapter.reopenInThisUnit !== false ||
471			receipt.frozenAdapter.redBuildPatchedAround !== false ||
472			receipt.frozenAdapter.recomputedByThisUnit !== true ||
473			!Array.isArray(receipt.frozenAdapter.subtrees) ||
474			receipt.frozenAdapter.subtrees.length !== 5 ||
475			sha256(holdoutReactCypressRwaWitnessPreimage(receipt.frozenAdapter.subtrees)) !==
476				receipt.frozenAdapter.compositeFingerprint
