48	export function resolveReceiptPath(
49		value: string,
50		repositoryRoot: string,
51		base: ReceiptPathBase,
52	): string {
53		if (path.isAbsolute(value)) return path.normalize(value);
54		const explicitBase =
55			base === 'repository'
56				? path.normalize(repositoryRoot)
57				: path.join(path.normalize(repositoryRoot), '.versionless');
58		return path.resolve(explicitBase, value);
59	}
