			},
			holdoutSpecificConfiguration: 'none',
			applicationFilesHandEdited: 0,
		},
		cell: {
			id: 'angular-16-browser-builder',
			angularLine: '16.2',
			builder: '@angular-devkit/build-angular:browser',
			node: '16.20.2',
		},
		lanes: {
			baseline: {
