				path: witness.mutation.path,
				offset: witness.mutation.offset,
				beforeSha256: witness.mutation.beforeSha256,
				mutatedSha256: witness.mutation.mutatedSha256,
				afterRestoreSha256: witness.mutation.afterRestoreSha256,
