	renderHoldoutAngularEshopWebspaReceipt,
	HOLDOUT_ANGULAR_ESHOP_WEBSPA_RECEIPT_PATH,
	HOLDOUT_ANGULAR_ESHOP_WEBSPA_MARKDOWN_PATH,
	holdoutAngularEshopWebspaCorpusRecord,
} from '../../../../../packages/core/src/receipts/holdout-angular-eshop-webspa.ts';

