const receipt = await deriveHoldoutAngularEshopWebspaReceipt(root);
await writeFile(
	join(root, HOLDOUT_ANGULAR_ESHOP_WEBSPA_RECEIPT_PATH),
	`${JSON.stringify(receipt, null, 2)}\n`,
);
await writeFile(
	join(root, HOLDOUT_ANGULAR_ESHOP_WEBSPA_MARKDOWN_PATH),
	renderHoldoutAngularEshopWebspaReceipt(receipt),
);
console.log(JSON.stringify({ digest: receipt.integrity.canonicalDigest }));
console.log(JSON.stringify(holdoutAngularEshopWebspaCorpusRecord(receipt), null, 2));

