	'identity',
	'basket',
	'orders',
	'campaigns',
	'signalr',
	'text-entry',
	'drag',
]);
expect(eshopExpected.countedInLineageNumerator).toBe(false);
expect(eshopExpected.countingNote).toContain("Judge's decision");

